from typing import FrozenSet, Iterable, Mapping
Face = FrozenSet[str]

def closure(maxima: Iterable[Iterable[str]]) -> frozenset[Face]:
    faces: set[Face] = set()
    for maximum in maxima:
        values = tuple(maximum)
        for k in range(len(values) + 1):
            faces.update(frozenset(x) for x in combinations(values, k))
    return frozenset(faces)

